    fn parse(input: ParseStream<'_>) -> syn::Result<Self> {
        if input.peek(syn::Ident) {
            let fork = input.fork();
            let ident = fork.parse::<syn::Ident>()?;

            if ident == "result" && fork.peek(Token![=]) {
